<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();try{$q=db()->prepare("INSERT INTO users(name,username,password,role,department_id) VALUES(?,?,?,'lecturer',?)");$q->execute([trim($_POST['name']),trim($_POST['username']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_SESSION['user']['department_id']]);flash('Lecturer created.');redirect('/hod/lecturers/index.php');}catch(PDOException $e){$error='Username is already in use.';}}$title='Add Lecturer';require __DIR__.'/../../includes/header.php';?><section class="panel"><h2>Add Lecturer</h2><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Full Name<input name="name" required></label><label>Username<input name="username" required></label><label>Password<input type="password" name="password" minlength="6" required></label><button>Create Lecturer</button></form></section><?php require __DIR__.'/../../includes/footer.php';?>
